-- V30: 补全「商品替换」「商品换背景」两个分类的表单 schema
--
-- 背景：V28 只配了参考站截图里那三个工具，其余工具 form_schema 为空，前台退回
-- 「按 form 推导上传槽」的旧渲染 —— 能用，但所有工具长得一模一样，参数也没得选。
--
-- 这一版和 V31 把剩下 52 个工具逐个配上：上传槽按业务语义命名（鞋款图 / 首饰图 /
-- 手部参考图），字段是该工具真正关心的选项，右栏补使用说明。
--
-- 幂等写法：`AND form_schema IS NULL`。
--   - 重复执行不会重复写；
--   - 更重要的一点是**不覆盖运营的线上改动** —— schema 现在是后台可编辑的数据，
--     迁移只负责把空缺填上，不负责把人家改过的再改回去。
--
-- 不含 scene-prop-replace-copy：那是运营在后台点「复制」生成的临时条目，
-- 迁移不该为它负责（新环境里根本不存在这一行）。

/* ------------------------------ 商品替换 ------------------------------ */

-- 场景道具替换器：换掉场景里的一件道具，商品本身不动
UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"主体商品保持完整清晰"},{"key":"replacement","label":"上传替换道具图","required":true,"hint":"期望出现在场景里的那件道具"}],"fields":[{"key":"propType","type":"select","label":"道具类型","placeholder":"请选择道具类型","options":["绿植花艺","家居摆件","装饰雕塑","厨房道具","运动器材","休闲家具"]},{"key":"placement","type":"select","label":"摆放位置","options":["商品左侧","商品右侧","商品后方","环绕商品"]},{"key":"perspective","type":"select","label":"透视处理","options":["自动匹配原图","保持原透视","轻微调整"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：道具不要遮挡商品 logo"}],"guide":{"intro":"把商品图里的道具换成你指定的那一件，并按原图的透视、光源与阴影重新贴合，商品本身不重新生成。","steps":["上传商品图与替换道具图","选择道具类型与摆放位置","提交后模型按原透视融合"],"tips":["道具图尽量用白底实物，边缘越干净越好","原图有明确的桌面或地面时，位置判断更准"]},"credits":{"perImage":2}}' WHERE tool_key = 'scene-prop-replace' AND form_schema IS NULL;

-- 季节氛围替换大师：重建环境，季节元素与色调一起给
UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"主体商品，保持完整"},{"key":"background","label":"上传参考背景图","required":false,"hint":"可选，用于锁定场景风格"}],"fields":[{"key":"season","type":"chips","label":"目标季节","required":true,"multiple":true,"options":["春","夏","秋","冬"]},{"key":"elements","type":"chips","label":"氛围元素","multiple":true,"options":["飘雪","落叶","樱花","暖阳","雨滴","薄雾","灯串"]},{"key":"tone","type":"select","label":"整体色调","options":["温暖明亮","清冷通透","柔和低饱和","浓郁对比"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：保留商品原有的冷色调，只改环境"}],"guide":{"intro":"按季节重建商品所处环境：光线、色温、地面与氛围元素一起换，让同一件商品在不同季节都能用。","steps":["上传商品图，可附一张参考背景","勾选目标季节与氛围元素","选择色调后提交"],"tips":["一次只选一个季节，混搭容易出怪图","商品是浅色时不建议配飘雪，容易融在一起"]},"credits":{"perImage":2}}' WHERE tool_key = 'season-atmosphere' AND form_schema IS NULL;

-- 商品场景迁移大师：整张图搬到新场景
UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"建议包含完整的商品主体"},{"key":"background","label":"上传目标场景图","required":false,"hint":"可选，不给则由模型按场景类型生成"}],"fields":[{"key":"targetScene","type":"select","label":"目标场景","required":true,"options":["室内家居","户外自然","都市街景","专业影棚","度假海岛","复古空间"]},{"key":"lighting","type":"select","label":"光线类型","options":["自然光","柔光棚拍","逆光轮廓","暖黄氛围光","冷调环境光"]},{"key":"perspective","type":"select","label":"透视处理","options":["自动匹配新场景","保持商品原角度","轻微俯视","轻微仰视"]}],"guide":{"intro":"把商品从原图迁移到一个新的商业场景，重新生成环境光影与投影，保持商品材质和颜色不变。","steps":["上传商品图，必要时附目标场景图","选择目标场景与光线","提交后模型重建环境"],"tips":["商品带透明或白色边缘时，先抠图再迁移更干净","目标场景图与商品的视角越接近，融合越自然"]},"credits":{"perImage":2}}' WHERE tool_key = 'scene-migration' AND form_schema IS NULL;

-- 手持模特替换专家：商品 + 手部参考
UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"将被手持的商品，建议白底"},{"key":"model","label":"上传手部参考图","required":true,"hint":"包含手部姿态的参考图，用于定姿势"}],"fields":[{"key":"handPose","type":"select","label":"持握方式","options":["自然持握","托举特写","单手展示","双手展示"]},{"key":"skinTone","type":"select","label":"肤色","options":["自动匹配参考图","白皙","自然","小麦"]},{"key":"nailStyle","type":"select","label":"指甲处理","options":["不处理","裸色","法式","纯色"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：手指不要遮挡品牌标签"}],"guide":{"intro":"生成手部持握商品的展示图：手型、肤色与光线跟参考图走，商品保持原有材质与标签。","steps":["上传商品图与手部参考图","选择持握方式与肤色","提交后生成持握效果"],"tips":["参考图里手部完整、光线均匀时效果最稳","小件商品建议用「托举特写」，比例更准"]},"credits":{"perImage":2}}' WHERE tool_key = 'hand-model-replace' AND form_schema IS NULL;

-- 产品包装替换器
UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传产品图","required":true,"hint":"需要换包装的产品主体"},{"key":"replacement","label":"上传包装图","required":true,"hint":"目标包装，含品牌标识更佳"}],"fields":[{"key":"packageType","type":"select","label":"包装类型","required":true,"options":["纸盒","铁盒","礼盒","瓶身","袋装","罐装"]},{"key":"keepLabel","type":"select","label":"品牌文字","options":["完整保留原标识","替换为包装图上的标识","不显示文字"]},{"key":"material","type":"select","label":"包装材质","options":["哑光","亮面","金属","牛皮纸","磨砂塑料"]}],"guide":{"intro":"把产品的包装换成指定款式，保留品牌标识的位置与清晰度，产品形态和内容物不变。","steps":["上传产品图与包装图","选择包装类型、材质与标识处理方式","提交后生成新包装效果"],"tips":["包装图正面朝向镜头，标签文字最清楚","瓶身类包装建议同时给出侧面图，圆弧更真实"]},"credits":{"perImage":2}}' WHERE tool_key = 'package-replace' AND form_schema IS NULL;

-- 产品部件替换工具
UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传产品图","required":true,"hint":"需要改部件的产品全貌"},{"key":"replacement","label":"上传替换部件图","required":true,"hint":"目标部件，视角尽量与产品一致"}],"fields":[{"key":"partType","type":"select","label":"部件类型","required":true,"options":["瓶盖","喷头","按键","把手","底座","装饰配件"]},{"key":"blend","type":"select","label":"融合程度","options":["低（边缘清晰）","中（贴合材质）","高（完全融入）"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：只换底部硅胶垫，其余不动"}],"guide":{"intro":"只替换产品的某一个部件，周围的材质、光影和比例保持原样，适合改配色或换配件版本。","steps":["上传产品图与部件图","选择部件类型与融合程度","提交后局部重绘"],"tips":["部件图和产品的拍摄角度一致，贴合才自然","融合程度调高会让接缝变软，硬质部件别调太高"]},"credits":{"perImage":2}}' WHERE tool_key = 'component-replace' AND form_schema IS NULL;

-- 商品材质替换器
UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"外形保持不变的商品主体"},{"key":"replacement","label":"上传材质图","required":false,"hint":"可选，提供目标材质的平铺图"}],"fields":[{"key":"materialType","type":"select","label":"目标材质","required":true,"options":["皮革","金属","木质","陶瓷","织物","玻璃","大理石","绒面"]},{"key":"glossiness","type":"select","label":"光泽度","options":["哑光","半哑","高光"]},{"key":"textureScale","type":"select","label":"纹理大小","options":["细腻","适中","粗犷"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：保留原有缝线和五金件"}],"guide":{"intro":"把商品表面换成另一种材质，保留原有外形轮廓、结构线与配件，只改表面质感。","steps":["上传商品图，可选附材质贴图","选择目标材质、光泽度与纹理大小","提交后重绘表面"],"tips":["结构线清楚的产品（比如带缝线的包）效果最好","玻璃与金属建议配「高光」，否则看起来像塑料"]},"credits":{"perImage":2}}' WHERE tool_key = 'material-replace' AND form_schema IS NULL;

/* ------------------------------ 商品换背景 ------------------------------ */

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"自动抠图，主体越完整越好"},{"key":"background","label":"上传背景图","required":false,"hint":"可选，不给则按场景类型生成"}],"fields":[{"key":"scene","type":"select","label":"背景类型","required":true,"options":["纯色背景","渐变背景","生活场景","专业影棚","自然风光","质感台面"]},{"key":"tone","type":"select","label":"色调","options":["明亮通透","柔和低饱和","高级灰","暖调","冷调"]},{"key":"shadow","type":"select","label":"阴影处理","options":["保留原阴影","重新生成地面阴影","无阴影"]}],"guide":{"intro":"一键抠出商品主体并放到新背景上，重新匹配边缘、投影与色温，避免出现贴纸感。","steps":["上传商品图，可附背景图","选择背景类型、色调与阴影","提交后生成成片"],"tips":["半透明商品（玻璃瓶、纱）建议选「质感台面」，边缘更自然","需要保留原图光感时选「保留原阴影」"]},"credits":{"perImage":2}}' WHERE tool_key = 'one-click-background' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"需要校正光影的成片"},{"key":"background","label":"上传背景参考图","required":false,"hint":"可选，用于对齐目标光线方向"}],"fields":[{"key":"lightDirection","type":"select","label":"主光方向","options":["左上","右上","正面","侧逆光","顶光"]},{"key":"perspective","type":"select","label":"透视关系","options":["自动匹配","平视","俯视","仰视"]},{"key":"intensity","type":"select","label":"光比强度","options":["柔和","标准","强烈"]}],"guide":{"intro":"修正商品与背景之间光影和透视不一致的问题：统一光源方向，补上合理的投影与反射。","steps":["上传商品图，可附背景参考","指定主光方向与视角","提交后校正光影"],"tips":["原图光向越明确，校正结果越可信","光比调到「强烈」会加深阴影，适合硬朗的工业品"]},"credits":{"perImage":2}}' WHERE tool_key = 'light-perspective' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"主体商品，建议白底"},{"key":"background","label":"上传风格参考图","required":false,"hint":"可选，提供想参考的画面风格"}],"fields":[{"key":"style","type":"chips","label":"艺术风格","multiple":true,"options":["水彩","油画","几何","极简","复古","赛博"]},{"key":"palette","type":"select","label":"配色方案","options":["冷色","暖色","莫兰迪","高饱和","黑白"]},{"key":"density","type":"select","label":"画面密度","options":["大量留白","适中","元素丰富"]}],"guide":{"intro":"为商品生成有艺术感的背景画面，风格和配色按需指定，商品本体保持真实。","steps":["上传商品图，可附风格参考","勾选艺术风格与配色","选择画面密度后提交"],"tips":["风格一次选一到两种，叠加太多会互相打架","要放卖点文字的话，把密度调低留出空间"]},"credits":{"perImage":2}}' WHERE tool_key = 'artistic-background' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"支持一次上传多张，逐张处理"}],"fields":[{"key":"uniformScene","type":"select","label":"统一背景","required":true,"options":["纯白","浅灰","木纹","大理石","纯色"]},{"key":"uniformTone","type":"select","label":"统一色调","options":["保持原色","统一偏暖","统一偏冷","统一提亮"]},{"key":"keepShadow","type":"select","label":"投影","options":["统一加柔和投影","保留各自原本投影","不加投影"]},{"key":"note","type":"textarea","label":"补充说明","placeholder":"例如：所有商品主体占画面 70%"}],"guide":{"intro":"把一批商品图处理成同一套背景、同一色调和统一的主体占比，适合店铺首页批量上新。","steps":["一次上传多张商品图","选择统一背景与色调","提交后逐张输出"],"tips":["同一批图尽量用相近的拍摄角度，观感才整齐","这功能不改变商品本身，只统一环境"]},"credits":{"perImage":1}}' WHERE tool_key = 'batch-background' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"家居类商品效果最好"},{"key":"background","label":"上传空间参考图","required":false,"hint":"可选，指定真实房间"}],"fields":[{"key":"room","type":"select","label":"房间类型","required":true,"options":["客厅","卧室","餐厅","书房","浴室","阳台"]},{"key":"style","type":"select","label":"装修风格","options":["北欧","现代简约","日式","中古","奶油风","工业风"]},{"key":"lighting","type":"select","label":"光源","options":["自然窗光","暖色灯光","顶部主光","混合光"]}],"guide":{"intro":"把商品放进真实的家居空间里，保留房间陈设与光线，让商品看起来就像摆在用户家里。","steps":["上传商品图，可附空间参考图","选择房间类型与装修风格","提交后融合进场景"],"tips":["商品尺寸信息越明确，摆放比例越合理","同一店铺统一风格，页面观感更成体系"]},"credits":{"perImage":2}}' WHERE tool_key = 'home-background' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"数码产品建议正面清晰"},{"key":"background","label":"上传参考背景图","required":false,"hint":"可选，指定想要的科技感场景"}],"fields":[{"key":"scene","type":"select","label":"场景类型","required":true,"options":["实验室","工作台","暗场光效","电路纹理","未来空间"]},{"key":"lightColor","type":"select","label":"光效颜色","options":["蓝色","青色","紫色","白色","橙色"]},{"key":"glow","type":"select","label":"光效强度","options":["弱","中","强"]}],"guide":{"intro":"给数码产品配一套科技质感背景：暗场、光束、电路或实验室台面，突出金属与玻璃的反光。","steps":["上传商品图，可附参考背景","选择场景与光效颜色","调整光效强度后提交"],"tips":["深色产品用青色或紫色光效更出彩","光效太强会吃掉产品细节，先试「中」"]},"credits":{"perImage":2}}' WHERE tool_key = 'tech-background' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"食品、饮品、餐具类适用"},{"key":"background","label":"上传场景参考图","required":false,"hint":"可选，指定餐桌或操作台"}],"fields":[{"key":"scene","type":"select","label":"陈列场景","required":true,"options":["木质餐桌","大理石台面","野餐布","厨房操作台","餐厅桌面"]},{"key":"props","type":"chips","label":"搭配道具","multiple":true,"options":["餐具","新鲜食材","花卉","餐布","无道具"]},{"key":"appetite","type":"select","label":"食欲感","options":["暖食欲光","自然日光","冷调高级"]}],"guide":{"intro":"生成有食欲的美食场景：桌面材质、配菜道具和暖光一起给，让食品看起来刚出炉。","steps":["上传商品图，可附场景参考","选择陈列场景与搭配道具","选择食欲感后提交"],"tips":["暖食欲光最适合热食与烘焙","饮品建议搭配「大理石台面」加自然日光"]},"credits":{"perImage":2}}' WHERE tool_key = 'food-background' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传商品图","required":true,"hint":"瓶身、罐装、管状美妆产品"},{"key":"background","label":"上传质感参考图","required":false,"hint":"可选，指定亚克力、丝绸等质感"}],"fields":[{"key":"scene","type":"select","label":"质感场景","required":true,"options":["亚克力台面","丝绸","水波","极简纯色","花艺背景"]},{"key":"texture","type":"select","label":"表面质感","options":["哑光","水润","金属","雾面"]},{"key":"tone","type":"select","label":"色调","options":["清透","温柔粉调","高级灰","冷白"]}],"guide":{"intro":"为美妆产品生成高级质感背景：透明材质、水波、丝绸与柔光，突出瓶身的通透感与折射。","steps":["上传商品图，可附质感参考","选择质感场景与表面效果","选择色调后提交"],"tips":["透明瓶身配「水波」或「亚克力」，折射最漂亮","字体与 logo 要清楚的话，别用强反光的丝绸"]},"credits":{"perImage":2}}' WHERE tool_key = 'beauty-background' AND form_schema IS NULL;

UPDATE commerce_tools SET form_schema = '{"uploads":[{"key":"product","label":"上传服饰图","required":true,"hint":"单品平铺或模特上身皆可"},{"key":"background","label":"上传风格参考图","required":false,"hint":"可选，指定想要的画面氛围"}],"fields":[{"key":"scene","type":"select","label":"背景场景","required":true,"options":["影棚","城市街景","自然户外","室内家居","纯色"]},{"key":"style","type":"select","label":"风格取向","options":["高级时装","日常休闲","运动户外","复古文艺"]},{"key":"lighting","type":"select","label":"光线","options":["柔光棚拍","自然日光","硬光对比","黄昏暖光"]}],"guide":{"intro":"给服饰配一套符合风格定位的背景与光线，让主图、详情页和社媒素材保持同一套视觉语言。","steps":["上传服饰图，可附风格参考","选择背景场景与风格取向","选择光线后提交"],"tips":["同一季度的新品尽量用同一套场景参数","街景配硬光对比，出片更有杂志感"]},"credits":{"perImage":2}}' WHERE tool_key = 'fashion-background' AND form_schema IS NULL;
